/* Lot 112: var() and math functions in opacity keyframes and @starting-style (generated by scripts/lot112_gen.py; expectations from scripts/lot112_model.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_sitecss.h"

static wf_site_t g_d;
static char g_html[4096];
static char g_o[1024];

static void prep(const char *css, int ms) {
    wf_site_set_time(ms);
    snprintf(g_html, sizeof(g_html), "<html><head><style>%s</style></head><body>"
             "<div id=o><p id=i>i</p></div><p id=q>q</p></body></html>", css);
    TEST_ASSERT_EQUAL(0, wf_site_prepare_ext(&g_d, g_html, (int)strlen(g_html), 640, 480, 0, 0));
    wf_site_set_time(0);
}

static const char *style_of(const char *id) {
    int i;
    g_o[0] = 0;
    for (i = 0; i < g_d.nnodes; i++)
        if (!strcmp(g_d.node[i].id, id)) wf_site_style_attr(&g_d, g_d.node[i].start, g_o, (int)sizeof(g_o));
    return g_o;
}

static void test_l112_opk_0(void) {
    prep("@keyframes k { 50% { opacity: min(0.8, 0.6) } } body { --a: 0.75 } #o { --b: calc(0.5 / 2) } #o { animation: k 2s linear }", 750);
    TEST_ASSERT_EQUAL_STRING(" style=\"opacity:70%\"", style_of("o"));
    prep("@keyframes k { 0% { opacity: clamp(0, 2, 1) } } #o { opacity: calc(0.3 + 0.3); animation: k 1s linear 250ms } body { --b: 40% }", 0);
    TEST_ASSERT_EQUAL_STRING(" style=\"opacity:60%\"", style_of("o"));
    prep("@keyframes k { 50% { opacity: clamp(0, 2, 1) } } #o { --a: 0.2 } #o { animation: k 1s ease-in }", 750);
    TEST_ASSERT_EQUAL_STRING(" style=\"opacity:100%\"", style_of("o"));
    prep("@keyframes k { 50% { opacity: 1 } 100% { opacity: var(--b) } } #o { opacity: 0.5; animation: k 1s ease-in }", 663);
    TEST_ASSERT_EQUAL_STRING(" style=\"opacity:92%\"", style_of("o"));
    prep("@starting-style { #o { opacity: min(20%, 0.4) } } #o { opacity: 80%; transition: opacity 2s linear } #o { --a: 2 } #o { --b: 40% }", 1200);
    TEST_ASSERT_EQUAL_STRING(" style=\"opacity:80%\"", style_of("o"));
    prep("@starting-style { #o { opacity: 0 } } #o { --a: auto } #o { transition: opacity 2s linear }", 500);
    TEST_ASSERT_EQUAL_STRING(" style=\"opacity:25%\"", style_of("o"));
    prep("@starting-style { #o { opacity: var(--u) } } #o { --b: auto } #o { opacity: calc(0.3 + 0.3); transition: all 1s ease-in }", 250);
    TEST_ASSERT_EQUAL_STRING(" style=\"opacity:96%\"", style_of("o"));
    prep("@keyframes k { 25% { opacity: clamp(0, 2, 1) } to { opacity: clamp(0, 2, 1) } } #o { animation: k 1s linear }", 750);
    TEST_ASSERT_EQUAL_STRING(" style=\"opacity:100%\"", style_of("o"));
    prep("@keyframes k { to { opacity: var(--a) } } #o { animation: k 1s linear } body { --b: 40% }", 1200);
    TEST_ASSERT_EQUAL_STRING("", style_of("o"));
    prep("@starting-style { #o { opacity: min(20%, 0.4) } } #o { transition: opacity 1s linear } body { --a: 2 } body { --b: 40% }", 500);
    TEST_ASSERT_EQUAL_STRING("", style_of("o"));
}

static void test_l112_opk_1(void) {
    prep("@keyframes k { 100% { opacity: calc(var(--a) * 2) } } #o { animation: k 2s linear } #o { --a: 2 } body { --b: 0.75 }", 750);
    TEST_ASSERT_EQUAL_STRING(" style=\"opacity:100%\"", style_of("o"));
    prep("@keyframes k { 0% { opacity: var(--b) } } #o { --a: 0.1234 } body { --b: 0.2 } #o { animation: k 1s linear } #o { --b: 0.2 }", 1200);
    TEST_ASSERT_EQUAL_STRING("", style_of("o"));
    prep("@keyframes k { 50% { opacity: var(--u, 40%) } to { opacity: 1 } } #o { animation: k 2s linear } body { --a: 40% } #o { --a: auto } #o { --b: 0.1234 }", 750);
    TEST_ASSERT_EQUAL_STRING(" style=\"opacity:55%\"", style_of("o"));
    prep("@keyframes k { from { opacity: var(--b) } 25% { opacity: var(--a) } } #o { animation: k 1s linear 250ms } body { --b: 0.2 }", 750);
    TEST_ASSERT_EQUAL_STRING(" style=\"opacity:60%\"", style_of("o"));
    prep("@keyframes k { 50% { opacity: 0 } } body { --a: auto } #o { animation: k 2s linear }", 0);
    TEST_ASSERT_EQUAL_STRING(" style=\"opacity:100%\"", style_of("o"));
    prep("@starting-style { #o { opacity: var(--b) } } #o { --a: auto } body { --a: calc(0.5 / 2) } #o { transition: all 1s ease-in }", 250);
    TEST_ASSERT_EQUAL_STRING("", style_of("o"));
    prep("@keyframes k { from { opacity: calc(1 - 2) } 50% { opacity: var(--a, 0.3) } 100% { opacity: 1px } } #o { animation: k 1s ease-in } #o { --a: 0.75 } body { --b: 2 }", 750);
    TEST_ASSERT_EQUAL_STRING(" style=\"opacity:82%\"", style_of("o"));
    prep("@keyframes k { from { opacity: min(0.8, 0.6) } 25% { opacity: min(0.8, 0.6) } 50% { opacity: min(0.8, 0.6) } } #o { animation: k 2s linear } #o { --b: 0.1234 }", 0);
    TEST_ASSERT_EQUAL_STRING(" style=\"opacity:60%\"", style_of("o"));
    prep("@keyframes k { 25% { opacity: var(--u) } 50% { opacity: calc(var(--a) * 2) } } #o { animation: k 1s linear 250ms } body { --b: auto } #o { --a: 40% }", 750);
    TEST_ASSERT_EQUAL_STRING(" style=\"opacity:80%\"", style_of("o"));
    prep("@keyframes k { 100% { opacity: max(10%, 0.2) } } #o { --b: 0.75 } body { --b: 0.2 } #o { opacity: 80%; animation: k 1s linear 250ms }", 500);
    TEST_ASSERT_EQUAL_STRING(" style=\"opacity:80%\"", style_of("o"));
}

